    50      ctx->lowest_double = SAV_LOWEST_DOUBLE;
    51      ctx->highest_double = SAV_HIGHEST_DOUBLE;
    52
    53      ctx->bias = ctx->bswap ? byteswap_double(header->bias) : header->bias;
    54
    55      ctx->varinfo_capacity = SAV_VARINFO_INITIAL_CAPACITY;
    56
    57      if ((ctx->varinfo = readstat_calloc(ctx->varinfo_capacity, sizeof(spss_varinfo_t *))) == NULL) {
    58          sav_ctx_free(ctx);
    59          return NULL;
    60      }
    61
    62      ctx->io = io;
    63
    64      return ctx;
